class Solution {
    public int maximumScore(int[] nums, int[] multipliers) {
        int n = nums.length;
        int m = multipliers.length;
        int[][] dp = new int[m + 1][m + 1];

        for (int operation = m - 1; operation >= 0; operation--) {
            int multiplier = multipliers[operation];
            for (int leftTaken = operation; leftTaken >= 0; leftTaken--) {
                int rightIndex = n - 1 - (operation - leftTaken);
                int takeLeft = multiplier * nums[leftTaken] + dp[operation + 1][leftTaken + 1];
                int takeRight = multiplier * nums[rightIndex] + dp[operation + 1][leftTaken];
                dp[operation][leftTaken] = Math.max(takeLeft, takeRight);
            }
        }
        return dp[0][0];
    }
}

class Solution {
    private int[] nums;
    private int[] multipliers;
    private Integer[][] memo;

    public int maximumScore(int[] nums, int[] multipliers) {
        this.nums = nums;
        this.multipliers = multipliers;
        this.memo = new Integer[multipliers.length][multipliers.length + 1];
        return dfs(0, 0);
    }

    private int dfs(int operation, int leftTaken) {
        if (operation == multipliers.length) {
            return 0;
        }
        if (memo[operation][leftTaken] != null) {
            return memo[operation][leftTaken];
        }

        int rightIndex = nums.length - 1 - (operation - leftTaken);
        int multiplier = multipliers[operation];
        int takeLeft = multiplier * nums[leftTaken] + dfs(operation + 1, leftTaken + 1);
        int takeRight = multiplier * nums[rightIndex] + dfs(operation + 1, leftTaken);
        memo[operation][leftTaken] = Math.max(takeLeft, takeRight);
        return memo[operation][leftTaken];
    }
}

class Solution {
    public int maximumScore(int[] nums, int[] multipliers) {
        int n = nums.length;
        int m = multipliers.length;
        int[] next = new int[m + 1];

        for (int operation = m - 1; operation >= 0; operation--) {
            int[] current = new int[m + 1];
            int multiplier = multipliers[operation];
            for (int leftTaken = operation; leftTaken >= 0; leftTaken--) {
                int rightIndex = n - 1 - (operation - leftTaken);
                int takeLeft = multiplier * nums[leftTaken] + next[leftTaken + 1];
                int takeRight = multiplier * nums[rightIndex] + next[leftTaken];
                current[leftTaken] = Math.max(takeLeft, takeRight);
            }
            next = current;
        }
        return next[0];
    }
}

class Solution {
    public int maximumScore(int[] nums, int[] multipliers) {
        int n = nums.length;
        int m = multipliers.length;
        int unreachable = Integer.MIN_VALUE / 4;
        int[] current = new int[m + 1];
        java.util.Arrays.fill(current, unreachable);
        current[0] = 0;

        for (int operation = 0; operation < m; operation++) {
            int[] next = new int[m + 1];
            java.util.Arrays.fill(next, unreachable);
            int multiplier = multipliers[operation];
            for (int leftTaken = 0; leftTaken <= operation; leftTaken++) {
                int score = current[leftTaken];
                if (score == unreachable) {
                    continue;
                }
                int rightIndex = n - 1 - (operation - leftTaken);
                next[leftTaken + 1] = Math.max(next[leftTaken + 1], score + multiplier * nums[leftTaken]);
                next[leftTaken] = Math.max(next[leftTaken], score + multiplier * nums[rightIndex]);
            }
            current = next;
        }

        int answer = Integer.MIN_VALUE;
        for (int leftTaken = 0; leftTaken <= m; leftTaken++) {
            answer = Math.max(answer, current[leftTaken]);
        }
        return answer;
    }
}
